/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import { loadFont as loadSans } from "@remotion/google-fonts/InterTight";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useCallback,
  useContext,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  getRemotionEnvironment,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  Sequence,
  type SequenceControls,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * A stack of shots flicked through, collapsing into the mark, and the wordmark
 * landing beside it.
 *
 * One square card holds the middle of the frame and cuts to the next shot, each
 * one smaller and each held for less time than the last, so the sequence winds
 * itself up rather than running at a constant clip. At the end of the run the
 * card does not shrink away — it *collapses*, overshooting past its resting size
 * in a frame and settling back. Then the mark steps aside and the wordmark takes
 * the space it made.
 *
 * ## The cuts are cuts
 *
 * Nothing cross-fades and nothing tweens between shots. The reference holds each
 * card at a fixed size for its whole beat — measured, the box is constant to the
 * pixel across every frame of a hold, and then a different size on the next one.
 * A card that eased between sizes would read as a zoom; a card that cuts reads as
 * a stack of prints being dealt, which is the whole idea.
 *
 * That is also why `sizes` and `holds` are parallel lists of literals rather than
 * a ratio and a duration. The reference's own run is 0.512, 0.476, 0.458, 0.414,
 * 0.339 of the frame height on beats of 1, 6, 5, 4, 2 and 4 frames — neither
 * series is geometric, and a formula that fitted one would miss the other.
 *
 * ## The collapse overshoots
 *
 * 30px, then 24, then 22, on three consecutive frames. Two frames of overshoot is
 * the difference between a mark that lands and a mark that is simply smaller than
 * the card was — and it is the only place in the scene where anything moves
 * between frames rather than cutting.
 *
 * ## The mark steps aside in two
 *
 * Centred alone at 294.5; then 282.0 for four frames; then 248.5 as the wordmark
 * appears whole. Two steps, held, not an ease — the same grammar as the cards.
 */

const { fontFamily: SANS } = loadSans("normal", {
  weights: ["600", "700"],
  subsets: ["latin"],
});

/* ─────────────────────────────────────────────────────────────────────────
   The stage, in the recording's own 592 × 336 pixels
   ───────────────────────────────────────────────────────────────────────── */

const REF_W = 592;
const REF_H = 336;

/** Where the card, and then the mark, sits. */
const STAGE_X = 294;
const STAGE_Y = 167.5;

/**
 * The mark's box, frame by frame, from the moment the stack runs out.
 *
 * It lands oversized and settles in three steps rather than easing: 32, 25, 24,
 * then 23 for the rest of the scene. Measured on the mark's orange core, which
 * is the only part of it a threshold can find honestly — the glow around it
 * reads as ink to anything looser and makes the landing look 40% bigger than it
 * is.
 */
const MARK = 22;
const LAND: readonly number[] = [32, 25, 24, 24];

/**
 * The tile the stack collapses onto, before the mark is left alone.
 *
 * This is the beat that is easy to miss and impossible to unsee: the photo card
 * does not shrink into the mark, it *cuts* to a plain light tile of 60px with
 * the mark sitting on it, holds for two frames, and only then does the tile go.
 * It is very faint — luma 233 against the page's 247, which is why nothing
 * thresholded at 200 finds it — and it is what makes the collapse read as a
 * stack of prints resolving into a logo rather than as a card that shrank.
 */
const TILE = 60;
const TILE_FRAMES = 2;

/** Left edge of the finished lockup, and where the word starts inside it. */
const LOCK_X = 237;
const WORD_X = 264;

/** Cap height of the wordmark, measured on its own ink. */
const WORD_CAP = 19.37;
/** Top of the wordmark's box. Measured, not derived from a line-height ratio. */
const WORD_TOP = 155.74;
/**
 * Cap height → font-size, and the tracking a logotype is set at.
 *
 * A wordmark is lettering, not type: the reference's is 4.149 cap-widths for six
 * glyphs, and the nearest face on the shelf sets the same six at 4.634 — twelve
 * per cent loose. That gap is tracking, not the wrong face. Inter Tight at
 * −0.073em closes it; every other candidate measured wider still (Archivo 4.786,
 * Plus Jakarta 4.877, Space Grotesk 4.975, Manrope 5.011, Poppins 5.715).
 */
const WORD_EM = 1.326;
const WORD_TRACK = -0.073;

/** The mark's waypoint: where it waits before the wordmark arrives. */
const STEP_X = 281.5;

/** Frames, on the scene's own 30fps clock. */
const STEP_AT = 28;
const WORD_AT = 30;
const DOT_AT: readonly number[] = [37, 42];

/**
 * The two marks that bracket the lockup, and the ping each one arrives on.
 *
 * They do not simply appear: each lands at 7px in full accent and settles to 4px
 * and about a third of its ink over five frames. Measured on both — the upper
 * one is already pale and small by the frame the lower one lands, which is the
 * only reason you can tell they are two beats and not one.
 */
const DOTS: readonly (readonly [number, number])[] = [
  [229, 147],
  [229, 191],
];
const DOT_IN = 7;
const DOT_OUT = 4;
const DOT_SETTLE = 5;
const DOT_FADE = 0.34;

export interface LogoCollapseProps {
  /**
   * The shots, split by `|`. The card cuts through them in order.
   *
   * Not by comma: a `data:` URL has one of its own right after the encoding, and
   * splitting on it hands the browser half a URL and a card that renders as a
   * broken-image glyph.
   */
  images?: string;
  /**
   * Each shot's card, as a share of the frame height.
   *
   * `0.48` is a square; `0.515x0.5625` is a portrait one. Real photo sets are
   * not all one shape, and the reference's second shot is measurably taller
   * than it is wide — forcing it square crops fifteen pixels off a print that
   * was never square.
   */
  sizes?: string;
  /** Frames each shot is held for. */
  holds?: string;
  /** The mark the stack collapses into. */
  mark?: string;
  /** The word that lands beside it. */
  wordmark?: string;
  /** Optional plate behind everything — a paper, a gradient, a still. */
  background?: string;
  /** The brand colour the two bracket marks ping in. Blank uses the accent. */
  accent?: string;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  fontFamily?: string;
}

function LogoCollapseScene({
  images = "",
  sizes = "0.82x0.461,0.72x0.405,0.63x0.354,0.55x0.309,0.46x0.259,0.36x0.203",
  holds = "1,5,5,4,2,5",
  mark = staticFile("logo-collapse/logo.png"),
  wordmark = "acme",
  background = "",
  accent = "",
  theme,
  mode = "light",
  fontFamily = "Default",
}: LogoCollapseProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily) ?? SANS;

  const u = height / REF_H;
  const ox = (width - REF_W * u) / 2;

  const shots = images
    .split("|")
    .map((s) => s.trim())
    .filter(Boolean);
  const size = sizes.split(",").map((s) => {
    const [w, h] = s.trim().split("x");
    const sw = Number(w);
    return [sw, h === undefined ? sw : Number(h)] as const;
  });
  const hold = holds.split(",").map((s) => Number(s.trim()));

  // Which shot is up, and the frame the stack runs out on.
  let at = 0;
  let shot = -1;
  for (let i = 0; i < shots.length; i++) {
    const end = at + (hold[i] ?? 0);
    if (frame < end) {
      shot = i;
      break;
    }
    at = end;
  }
  const collapseAt = hold
    .slice(0, shots.length)
    .reduce((a, b) => a + (b || 0), 0);

  const ink = t.foreground;

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ backgroundColor: t.background }}
    >
      {background && (
        <Plate
          src={background}
          style={{ position: "absolute", inset: 0, objectFit: "cover" }}
        />
      )}
      <div
        style={{
          position: "absolute",
          left: ox,
          top: 0,
          width: REF_W * u,
          height: REF_H * u,
          fontFamily: face,
          textRendering: "geometricPrecision",
        }}
      >
        {shot >= 0 ? (
          <Item key={shot} index={shot}>
            <Plate
              src={shots[shot] ?? ""}
              style={box(
                (size[shot]?.[0] ?? 0.4) * REF_H,
                (size[shot]?.[1] ?? 0.4) * REF_H,
                STAGE_X,
                STAGE_Y,
                u,
              )}
            />
          </Item>
        ) : (
          <Lockup
            frame={frame}
            since={frame - collapseAt}
            mark={mark}
            word={wordmark}
            ink={ink}
            accent={accent || t.primary}
            tile={t.muted}
            u={u}
          />
        )}
      </div>
    </AbsoluteFill>
  );
}

/** A box of `w × h` reference pixels centred on `(cx, cy)`, in real pixels. */
function box(
  w: number,
  h: number,
  cx: number,
  cy: number,
  u: number,
): CSSProperties {
  return {
    position: "absolute",
    left: (cx - w / 2) * u,
    top: (cy - h / 2) * u,
    width: w * u,
    height: h * u,
    objectFit: "cover",
  };
}

/** The tile, the mark landing, stepping aside, and the word arriving. */
function Lockup({
  frame,
  since,
  mark,
  word,
  ink,
  accent,
  tile,
  u,
}: {
  /** The scene's own frame, which the beats below are written in. */
  frame: number;
  /** Frames since the stack ran out, which the landing is written in. */
  since: number;
  mark: string;
  word: string;
  ink: string;
  accent: string;
  tile: string;
  u: number;
}) {
  const size = LAND[since] ?? MARK;
  const worded = frame >= WORD_AT;
  const cx = worded ? LOCK_X + MARK / 2 : frame >= STEP_AT ? STEP_X : STAGE_X;
  return (
    <>
      {since < TILE_FRAMES && (
        <div
          style={{
            ...box(TILE, TILE, STAGE_X, STAGE_Y, u),
            background: tile,
          }}
        />
      )}
      <Plate src={mark} style={box(size, size, cx, STAGE_Y, u)} />
      {worded && (
        <div
          style={{
            position: "absolute",
            left: WORD_X * u,
            top: WORD_TOP * u,
            fontSize: WORD_CAP * WORD_EM * u,
            lineHeight: 1,
            fontWeight: 700,
            letterSpacing: `${WORD_TRACK}em`,
            color: ink,
            whiteSpace: "nowrap",
          }}
        >
          {word}
        </div>
      )}
      {DOTS.map(([dx, dy], i) => {
        const since = frame - (DOT_AT[i] ?? Number.POSITIVE_INFINITY);
        if (since < 0) return null;
        const k = Math.min(1, since / DOT_SETTLE);
        const d = DOT_IN + (DOT_OUT - DOT_IN) * k;
        return (
          <div
            key={`${dx}-${dy}`}
            style={{
              position: "absolute",
              left: (dx - d / 2) * u,
              top: (dy - d / 2) * u,
              width: d * u,
              height: d * u,
              background: accent,
              opacity: 1 + (DOT_FADE - 1) * k,
            }}
          />
        );
      })}
    </>
  );
}

/**
 * A root-relative asset is a `public/` file. Only the site's own Player serves
 * it at that path; Remotion Studio and a render know its URL through
 * `staticFile()` alone — so every environment but the Player rewrites it.
 */
function resolveSrc(src: string): string {
  const isLocal = src.startsWith("/") && !src.startsWith("//");
  if (!isLocal || getRemotionEnvironment().isPlayer) return src;
  // A value that already came out of staticFile() carries the static base
  // (`/static-<hash>/…`); running it through again would prefix it twice.
  const base = staticFile("_").slice(0, -2);
  if (base && src.startsWith(`${base}/`)) return src;
  try {
    return staticFile(src.replace(/^\/+/, ""));
  } catch {
    return src;
  }
}

/**
 * An image that holds the render until it has actually loaded.
 *
 * Without it a frame can be captured before the picture arrives and the card
 * comes out empty — invisible in the Player, where an image simply appears, and
 * silent in an mp4 until somebody watches it. Remotion's own `Img` is avoided for
 * the reason `hero-launch` documents: it awaits `decode()`, which the headless
 * compositor rejects for some progressive JPEGs and hangs the export.
 *
 * Takes a `ref` so Remotion Studio can outline a shot (see `Item`); its `style`
 * already arrives with Studio's merged in.
 */
const Plate = forwardRef<
  HTMLImageElement,
  {
    src: string;
    style: CSSProperties;
  }
>(function Plate({ src, style }, ref) {
  const [handle] = useState(() => delayRender(`logo-collapse: ${src}`));
  const release = useCallback(() => continueRender(handle), [handle]);
  return (
    // biome-ignore lint/performance/noImgElement: Remotion frame, not a Next route.
    <img // eslint-disable-line @remotion/warn-native-media-tag -- onLoad releases the frame; <Img> hangs on some JPEGs
      ref={ref}
      src={resolveSrc(src)}
      alt=""
      // Tailwind's preflight sets `img { max-width: 100% }`, which collapses an
      // image inside a shrink-to-fit box to zero pixels wide on the site while
      // rendering perfectly in an mp4. Size it here and say so.
      style={{ ...style, maxWidth: "none" }}
      onLoad={release}
      onError={release}
    />
  );
});

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one shot at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function LogoCollapsePainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}

/** Whether every box that clips `el`, up to `root`, leaves all of it showing. */
function LogoCollapseWhole(el: Element, root: Element): boolean {
  const r = el.getBoundingClientRect();
  for (let a = el.parentElement; a; a = a === root ? null : a.parentElement) {
    if (getComputedStyle(a).overflow === "visible") continue;
    const c = a.getBoundingClientRect();
    if (
      r.left < c.left - 1 ||
      r.top < c.top - 1 ||
      r.right > c.right + 1 ||
      r.bottom > c.bottom + 1
    )
      return false;
  }
  return true;
}
type LogoCollapseShotValues = {
  readonly image?: string;
};

type LogoCollapseShotProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  LogoCollapseShotValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this shot as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: LogoCollapseShotState) => void;
  };

/** What Studio is doing to one shot right now, which the stage applies to its node. */
type LogoCollapseShotState = {
  values: LogoCollapseShotValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const LogoCollapseShotSchema = {
  ...Interactive.baseSchema,
  image: {
    type: "asset",
    assetType: "image",
    default: undefined,
    description: "Image",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One shot: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the shot is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const LogoCollapseShotInner = forwardRef<
  Element,
  LogoCollapseShotProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      image,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it or it paints past its own box; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { image },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? LogoCollapsePainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const n = el.getBoundingClientRect();
      if (
        LogoCollapseWhole(el, root) &&
        b[0] >= n.left - 1 &&
        b[1] >= n.top - 1 &&
        b[2] <= n.right + 1 &&
        b[3] <= n.bottom + 1
      ) {
        box.style.display = "none";
        target.current = el;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Shot"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

const LogoCollapseShot = Interactive.withSchema({
  Component: LogoCollapseShotInner,
  componentName: "<LogoCollapseShot>",
  schema: LogoCollapseShotSchema,
  supportsEffects: false,
});

type LogoCollapseStageProps = InteractiveBaseProps &
  Omit<ComponentProps<typeof LogoCollapseScene>, "images"> & {
    readonly children?: ReactNode;
  };

/**
 * What a scene prop falls back to when Studio does not pass it, reset included.
 * The shots' own lists are here only for the scene's parameter defaults;
 * the stage always passes the ones its children build.
 */
const LogoCollapseDefaults = {
  images: "",
  sizes: "0.82x0.461,0.72x0.405,0.63x0.354,0.55x0.309,0.46x0.259,0.36x0.203",
  holds: "1,5,5,4,2,5",
  mark: staticFile("logo-collapse/logo.png"),
  wordmark: "acme",
  mode: "light",
  theme: { background: "transparent" },
} satisfies Partial<LogoCollapseStageProps> &
  Partial<Pick<ComponentProps<typeof LogoCollapseScene>, "images">>;

const LogoCollapseStageSchema = {
  ...Interactive.baseSchema,
  mark: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-collapse/logo.png"),
    description: "Mark",
  },
  wordmark: { type: "text-content", default: "acme", description: "Wordmark" },
  accent: {
    type: "color",
    default: undefined,
    description: "Bracket colour",
    keyframable: false,
  },
  mode: {
    type: "enum",
    default: "light",
    description: "Theme",
    variants: { light: {}, dark: {} },
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
} as const satisfies InteractivitySchema;

/** The scene's props, from its shots' values in order. */
const LogoCollapseFromItems = (o: readonly LogoCollapseShotValues[]) => ({
  images: o.map((x) => x.image ?? "").join("|"),
  holds: o.map((_, i) => [1, 5, 5, 4, 2, 5][i] ?? 5).join(","),
  sizes: o
    .map(
      (_, i) =>
        [
          "0.82x0.461",
          "0.72x0.405",
          "0.63x0.354",
          "0.55x0.309",
          "0.46x0.259",
          "0.36x0.203",
        ][Math.min(i, 5)],
    )
    .join(","),
});

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function LogoCollapseFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

/** The host, told the frame inside the Element — the one its layers' timing is in. */
function LogoCollapseHosted({
  host,
  children,
}: {
  host: (frame: number) => ItemHost;
  children: ReactNode;
}) {
  return (
    <ItemHostProvider value={host(useCurrentFrame())}>
      {children}
    </ItemHostProvider>
  );
}

/**
 * The scene, with its shots as children. It reads their values to lay
 * the scene out, and hands each one back the node the scene draws it as.
 */
const LogoCollapseStageInner = forwardRef<
  HTMLDivElement,
  LogoCollapseStageProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      children,
      ...props
    },
    ref,
  ) => {
    const outlineRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
    // One empty box per shot on the stage: the outline it falls back to,
    // which it moves over the part of itself that shows.
    const slots = useRef<{ current: HTMLDivElement | null }[]>([]);
    const slotFor = (i: number) => {
      slots.current[i] ??= { current: null };
      return slots.current[i];
    };
    // Every shot the file lists, by position: each keeps its layer.
    const all = Children.toArray(children).filter(
      isValidElement,
    ) as ReactElement<LogoCollapseShotProps>[];
    const claims = useRef<{ current: Element | null }[]>([]);
    const claimFor = (j: number) => {
      claims.current[j] ??= { current: null };
      return claims.current[j];
    };
    const rest = { ...LogoCollapseDefaults, ...props };
    // What Studio is doing to each shot that the file may not have yet.
    const [live, setLive] = useState<Record<number, LogoCollapseShotState>>({});
    const report = (j: number, state: LogoCollapseShotState) =>
      setLive((prev) =>
        JSON.stringify(prev[j]) === JSON.stringify(state)
          ? prev
          : { ...prev, [j]: state },
      );
    const merged = all.map((o, j) => {
      const st = live[j];
      return st
        ? {
            ...o.props,
            ...st.values,
            style: st.style,
            hidden: st.hidden,
            from: st.from,
            durationInFrames: st.durationInFrames,
          }
        : o.props;
    });
    // The ones the scene draws, in its order: the positions its `Item`s index.
    const kept = all
      .map((_, j) => j)
      .filter((j) =>
        ((x: LogoCollapseShotValues) => Boolean(x.image?.trim()))(
          merged[j] as LogoCollapseShotValues,
        ),
      );
    const built = LogoCollapseFromItems(
      kept.map((j) => merged[j] as LogoCollapseShotValues),
    );
    const host =
      (frame: number): ItemHost =>
      (index, node) => {
        const j = kept[index];
        const m = j === undefined ? undefined : merged[j];
        if (j === undefined || !m) return node;
        // The layer's own visibility and timing, which its Sequence would apply
        // if it held the node.
        const start = m.from ?? 0;
        if (
          m.hidden ||
          frame < start ||
          frame >= start + (m.durationInFrames ?? Number.POSITIVE_INFINITY)
        )
          return null;
        const own = node as ReactElement<{
          ref?: Ref<Element>;
          style?: CSSProperties;
        }>;
        return cloneElement(own, {
          ref: claimFor(j),
          style: { ...own.props.style, ...m.style },
          ...(m.image === undefined ? null : { src: m.image }),
        });
      };
    // The scene measures its copy once, on mount, so a saved edit remounts it.
    // An edit still being typed does not: the scene would restart on every
    // keystroke. The layers are outside it and never remount with it.
    const key = JSON.stringify({
      ...rest,
      ...LogoCollapseFromItems(
        all
          .filter((o) =>
            ((x: LogoCollapseShotValues) => Boolean(x.image?.trim()))(o.props),
          )
          .map((o) => o.props),
      ),
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Logo Collapse"}
        controls={controls}
        outlineRef={outlineRef}
        width={1280}
        height={720}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width: 640,
            height: 360,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
          }}
        >
          {/* First, so each box's ref is set before the objects that move it
              run their layout effects on a fresh mount. */}
          {all.map((_, j) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: one box per position
              key={j}
              ref={slotFor(j)}
              style={{
                position: "absolute",
                display: "none",
                pointerEvents: "none",
                opacity: 0,
              }}
            />
          ))}
          <div
            style={{
              position: "absolute",
              left: -316,
              top: -180,
              width: 1280,
              height: 720,
            }}
          >
            <LogoCollapseFade>
              <LogoCollapseHosted host={host}>
                <LogoCollapseScene key={key} {...rest} {...built} />
              </LogoCollapseHosted>
            </LogoCollapseFade>
          </div>
          {/* The layers, after the scene: its nodes are attached by the time
              they measure them. */}
          {all.map((o, j) =>
            cloneElement(o, {
              // biome-ignore lint/suspicious/noArrayIndexKey: one layer per position
              key: j,
              claim: claimFor(j),
              slot: slotFor(j),
              report: (state: LogoCollapseShotState) => report(j, state),
            }),
          )}
        </div>
      </Sequence>
    );
  },
);

const LogoCollapseStage = Interactive.withSchema({
  Component: LogoCollapseStageInner,
  componentName: "<LogoCollapseStage>",
  schema: LogoCollapseStageSchema,
  supportsEffects: false,
});

